// The page GitHub Pages serves for any missing URL under the site. It can be
// served at any depth, so every link is absolute, and it loads nothing else:
// styles are inline, there is no script beyond picking the stored theme, and
// it reads the same with or without a connection. It speaks all five
// languages at once, since a broken URL says nothing about the reader's.
import { esc, site } from './page.mjs';

const base = new URL(site).pathname;

export default function notFound(languages) {
	return `<!DOCTYPE html>
<!-- Generated by build.mjs from src/404.mjs and i18n/. Edit those and run: node build.mjs -->
<html lang="${languages[0].lang}">
	<head>
		<meta charset="utf-8">
		<title>404</title>
		<meta name="viewport" content="width=device-width, initial-scale=1">
		<meta name="robots" content="noindex">
		<meta name="color-scheme" content="light dark">
		<link rel="icon" href="${base}img/google_icon.ico">
		<script>
			try { var theme = localStorage.getItem('learn-to-google:theme'); if (theme) document.documentElement.setAttribute('data-theme', theme); } catch (e) {}
		</script>
		<style>
			:root { color-scheme: light; --bg: #fff; --ink: #333; --muted: #555; --bubble: #bfe9f9; }
			@media (prefers-color-scheme: dark) {
				:root:not([data-theme="light"]) { color-scheme: dark; --bg: #1c1c1e; --ink: #e2e2e2; --muted: #a6a6a6; --bubble: #1e4250; }
			}
			:root[data-theme="dark"] { color-scheme: dark; --bg: #1c1c1e; --ink: #e2e2e2; --muted: #a6a6a6; --bubble: #1e4250; }
			body { max-width: 34rem; margin: 0 auto; padding: 3rem 1.25rem; background: var(--bg); color: var(--ink); font: 1.0625rem/1.5 sans-serif; }
			h1 { position: relative; display: inline-block; margin: 0 0 2rem; padding: 0.25rem 1.5rem; border-radius: 0.25rem; background: var(--bubble); font-size: 3rem; line-height: 1.25; }
			h1::before { position: absolute; left: -0.5rem; top: 1.5rem; border-top: 0.5rem solid transparent; border-bottom: 0.5rem solid transparent; border-right: 0.5rem solid var(--bubble); content: ''; }
			section { margin-bottom: 1.5rem; }
			h2 { margin: 0; font-size: 1.125rem; }
			p { margin: 0.25rem 0 0; color: var(--muted); }
			a { font-weight: 700; }
		</style>
	</head>
	<body>
		<main>
			<h1>404</h1>
${languages.map((l) => `\t\t\t<section lang="${l.lang}">
				<h2>${esc(l.ui.notFound)}</h2>
				<p>${esc(l.ui.notFoundText)} <a href="${base}${l.dir}" hreflang="${l.lang}">${esc(l.ui.notFoundHome)}</a></p>
			</section>`).join('\n')}
		</main>
	</body>
</html>
`;
}
